~~However, just running _ngc_ inside the repo results in the following:~~

```javascript
ItemsComponent.ngComponentDef = i0.ɵɵdefineComponent({ type: ItemsComponent, selectors: [["app-items"]], factory: function ItemsComponent_Factory(t) { return new (t || ItemsComponent)(i0.ɵɵdirectiveInject(i0.ChangeDetectorRef)); }, inputs: { count: "count" }, features: [i0.ɵɵNgOnChangesFeature()], consts: 2, vars: 2, template: function ItemsComponent_Template(rf, ctx) { if (rf & 1) {
